import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useStore } from '@/store/useStore';
import { getLevelTitle } from '@/data/achievements';
import { Home, BookOpen, Gamepad2, Notebook, User, Users, LogOut, LogIn } from 'lucide-react';

const NAV_ITEMS = [
  { path: '/', label: '首页', icon: Home },
  { path: '/decoder', label: '解字器', icon: BookOpen },
  { path: '/game', label: '猜谜', icon: Gamepad2 },
  { path: '/notebook', label: '记录本', icon: Notebook },
  { path: '/community', label: '社区', icon: Users },
  { path: '/profile', label: '我的', icon: User },
];

export default function Navbar() {
  const location = useLocation();
  const navigate = useNavigate();
  const user = useStore((s) => s.user);
  const logout = useStore((s) => s.logout);

  const title = user ? getLevelTitle(user.exp).title : '游客';

  return (
    <header className="sticky top-0 z-50 border-b border-ink-muted/20 bg-paper/90 backdrop-blur-md">
      <div className="container mx-auto max-w-7xl px-4">
        <div className="flex h-16 items-center justify-between gap-4">
          {/* Logo */}
          <Link to="/" className="flex items-center gap-2 shrink-0">
            <div className="flex h-9 w-9 items-center justify-center rounded-md bg-cinnabar text-paper-light seal-stamp">
              <span className="text-lg">甲</span>
            </div>
            <span className="font-brush text-xl text-ink hidden sm:inline">字从甲骨来</span>
          </Link>

          {/* Nav */}
          <nav className="flex items-center gap-1 overflow-x-auto">
            {NAV_ITEMS.map((item) => {
              const Icon = item.icon;
              const active = location.pathname === item.path ||
                (item.path !== '/' && location.pathname.startsWith(item.path));
              return (
                <Link
                  key={item.path}
                  to={item.path}
                  className={`flex items-center gap-1.5 rounded-md px-3 py-1.5 text-sm transition-colors whitespace-nowrap ${
                    active
                      ? 'bg-ink text-paper-light'
                      : 'text-ink-light hover:bg-ink-muted/15 hover:text-ink'
                  }`}
                >
                  <Icon size={16} />
                  <span className="hidden md:inline">{item.label}</span>
                </Link>
              );
            })}
          </nav>

          {/* User */}
          <div className="flex items-center gap-2 shrink-0">
            {user ? (
              <>
                <div className="hidden sm:flex items-center gap-2 rounded-md bg-paper-dark px-3 py-1.5">
                  <div className="flex h-7 w-7 items-center justify-center rounded-full bg-bronze text-paper-light text-sm font-medium">
                    {user.avatar}
                  </div>
                  <div className="text-xs">
                    <div className="font-medium text-ink leading-tight">{user.username}</div>
                    <div className="text-ink-muted leading-tight">{title} · Lv.{user.level}</div>
                  </div>
                </div>
                <button
                  onClick={() => { logout(); navigate('/'); }}
                  className="rounded-md p-2 text-ink-muted hover:bg-ink-muted/15 hover:text-cinnabar transition-colors"
                  title="退出登录"
                >
                  <LogOut size={16} />
                </button>
              </>
            ) : (
              <Link
                to="/auth"
                className="flex items-center gap-1.5 rounded-md bg-cinnabar px-3 py-1.5 text-sm text-paper-light hover:bg-cinnabar-dark transition-colors"
              >
                <LogIn size={16} />
                <span>登录</span>
              </Link>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}
