import { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import {
  Search,
  X,
  Bookmark,
  BookmarkCheck,
  CheckCircle2,
  BookOpen,
  ChevronRight,
  LogIn,
} from 'lucide-react';
import { useStore } from '@/store/useStore';
import { ORACLE_CHARS, CATEGORY_LABELS } from '@/data/oracleChars';
import OracleGlyph, { EvolutionGlyph } from '@/components/OracleGlyph';
import ModeSwitcher from '@/components/ModeSwitcher';
import PictoCompare from '@/components/PictoCompare';

type CategoryFilter = 'all' | 'nature' | 'body' | 'animal' | 'object';

const FILTERS: { key: CategoryFilter; label: string }[] = [
  { key: 'all', label: '全部' },
  { key: 'nature', label: CATEGORY_LABELS.nature },
  { key: 'body', label: CATEGORY_LABELS.body },
  { key: 'animal', label: CATEGORY_LABELS.animal },
  { key: 'object', label: CATEGORY_LABELS.object },
];

export default function Decoder() {
  const user = useStore((s) => s.user);
  const learnedCharIds = useStore((s) => s.learnedCharIds);
  const addLearningRecord = useStore((s) => s.addLearningRecord);
  const addToNotebook = useStore((s) => s.addToNotebook);
  const removeFromNotebook = useStore((s) => s.removeFromNotebook);
  const isInNotebook = useStore((s) => s.isInNotebook);
  // 订阅 notebookEntries 以保证收藏状态变化时组件重渲染
  const notebookEntries = useStore((s) => s.notebookEntries);

  const [category, setCategory] = useState<CategoryFilter>('all');
  const [query, setQuery] = useState('');
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return ORACLE_CHARS.filter((ch) => {
      const matchCat = category === 'all' || ch.category === category;
      const matchQuery = !q || ch.modernChar.includes(query.trim()) || ch.pinyin.toLowerCase().includes(q);
      return matchCat && matchQuery;
    });
  }, [category, query]);

  const selected = selectedId ? ORACLE_CHARS.find((c) => c.id === selectedId) ?? null : null;
  const learned = selected ? learnedCharIds.includes(selected.id) : false;
  const inNotebook = selected ? isInNotebook(selected.id) : false;
  void notebookEntries; // 触发收藏状态重渲染

  return (
    <div className="min-h-screen">
      {/* ===== Header ===== */}
      <header className="border-b border-ink-muted/20 bg-paper-light/70 backdrop-blur-sm">
        <div className="container mx-auto max-w-7xl px-4 py-6 flex items-center justify-between gap-4">
          <div>
            <h1 className="font-brush text-4xl md:text-5xl text-ink">解字器</h1>
            <p className="text-sm text-ink-muted mt-1">逐字解构甲骨文 · 观象形之变 · 品造字之妙</p>
          </div>
          <ModeSwitcher />
        </div>
      </header>

      {/* ===== Filter bar ===== */}
      <section className="container mx-auto max-w-7xl px-4 py-6">
        <div className="flex flex-col md:flex-row md:items-center gap-3 md:gap-4">
          <div className="flex flex-wrap gap-2">
            {FILTERS.map((f) => (
              <button
                key={f.key}
                onClick={() => setCategory(f.key)}
                className={`px-3.5 py-1.5 rounded-md text-sm font-medium border transition-all ${
                  category === f.key
                    ? 'bg-cinnabar text-paper-light border-cinnabar shadow-sm'
                    : 'bg-paper-light text-ink-light border-ink-muted/30 hover:border-cinnabar/40'
                }`}
              >
                {f.label}
              </button>
            ))}
          </div>
          <div className="relative md:ml-auto md:w-72">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-ink-muted" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="搜索汉字或拼音…"
              className="w-full rounded-md border border-ink-muted/30 bg-paper-light py-2 pl-9 pr-3 text-sm text-ink placeholder:text-ink-muted/60 focus:outline-none focus:border-cinnabar/50"
            />
          </div>
        </div>
      </section>

      {/* ===== Character grid ===== */}
      <section className="container mx-auto max-w-7xl px-4 pb-16">
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 md:gap-4">
          {filtered.map((ch) => {
            const isLearned = learnedCharIds.includes(ch.id);
            return (
              <button
                key={ch.id}
                onClick={() => setSelectedId(ch.id)}
                className="ink-card rounded-xl p-4 flex flex-col items-center text-center group cursor-pointer"
              >
                <div className="relative">
                  <OracleGlyph char={ch} size={80} color="#3D3833" />
                  {isLearned && (
                    <span
                      className="absolute -top-1 -right-1 h-2.5 w-2.5 rounded-full bg-bronze ring-2 ring-paper-light"
                      title="已学"
                    />
                  )}
                </div>
                <span className="mt-2 font-serif text-2xl text-ink group-hover:text-cinnabar transition-colors">
                  {ch.modernChar}
                </span>
                <span className="text-xs text-ink-muted">{ch.pinyin}</span>
                <span className="mt-1.5 text-[10px] px-2 py-0.5 rounded bg-bronze/10 text-bronze-dark">
                  {CATEGORY_LABELS[ch.category]}
                </span>
              </button>
            );
          })}
        </div>
        {filtered.length === 0 && (
          <div className="text-center py-20 text-ink-muted">
            <Search className="mx-auto mb-3 opacity-40" size={32} />
            未找到匹配的甲骨文
          </div>
        )}
      </section>

      {/* ===== Detail drawer ===== */}
      {selected && (
        <>
          <div
            className="fixed inset-0 z-40 bg-ink/40 backdrop-blur-sm animate-fade-in"
            onClick={() => setSelectedId(null)}
          />
          <aside className="fixed right-0 top-0 z-50 h-full w-full max-w-[480px] bg-paper-light shadow-2xl overflow-y-auto animate-fade-in">
            <button
              onClick={() => setSelectedId(null)}
              className="absolute top-4 right-4 z-10 p-1.5 rounded-md bg-paper-dark/60 text-ink-light hover:bg-cinnabar hover:text-paper-light transition-colors"
              aria-label="关闭"
            >
              <X size={18} />
            </button>

            <div className="p-6 md:p-8">
              {/* Top: large glyph */}
              <div className="flex flex-col items-center text-center">
                <div className="rounded-xl bg-paper border border-ink-muted/20 p-5 gold-glow">
                  <OracleGlyph char={selected} size={160} animated color="#1A1814" />
                </div>
                <div className="mt-4 flex items-baseline gap-3">
                  <span className="font-serif text-5xl text-ink">{selected.modernChar}</span>
                  <span className="text-ink-muted text-lg">{selected.pinyin}</span>
                </div>
                <div className="mt-2 flex items-center gap-2 text-xs">
                  <span className="px-2 py-0.5 rounded bg-cinnabar/10 text-cinnabar-dark">部首 · {selected.radical}</span>
                  <span className="px-2 py-0.5 rounded bg-bronze/10 text-bronze-dark">{CATEGORY_LABELS[selected.category]}</span>
                  {learned && (
                    <span className="px-2 py-0.5 rounded bg-bronze/15 text-bronze-dark flex items-center gap-1">
                      <CheckCircle2 size={12} /> 已学
                    </span>
                  )}
                </div>
              </div>

              {/* Pictographic comparison */}
              <div className="mt-8">
                <PictoCompare char={selected} />
              </div>

              {/* Evolution timeline */}
              <div className="mt-8">
                <h3 className="font-xiaowei text-lg text-ink mb-3 flex items-center gap-2">
                  <BookOpen size={16} className="text-cinnabar" /> 字形演变
                </h3>
                <div className="flex items-start justify-between gap-1 overflow-x-auto pb-2">
                  {selected.evolution.map((form, i) => (
                    <div key={form.stage} className="flex items-start gap-1">
                      <div className="flex flex-col items-center w-16">
                        <div className="h-16 w-16 flex items-center justify-center rounded-md bg-paper border border-ink-muted/15">
                          <EvolutionGlyph form={form} modernChar={selected.modernChar} size={48} animated color="#3D3833" />
                        </div>
                        <span className="mt-1.5 text-xs text-ink-muted whitespace-nowrap">{form.label}</span>
                      </div>
                      {i < selected.evolution.length - 1 && (
                        <ChevronRight size={14} className="mt-6 text-ink-muted/50 shrink-0" />
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {/* Meaning */}
              <div className="mt-6">
                <h3 className="font-xiaowei text-lg text-ink mb-2">释义</h3>
                <p className="text-sm text-ink-light leading-relaxed">{selected.meaning}</p>
              </div>

              {/* Story */}
              <div className="mt-6 border-l-4 border-gold bg-gold/5 pl-4 py-3 rounded-r-md">
                <h3 className="font-xiaowei text-lg text-ink mb-2">造字故事</h3>
                <p className="text-sm text-ink-light leading-relaxed">{selected.story}</p>
              </div>

              {/* Actions */}
              <div className="mt-8">
                {user ? (
                  <div className="flex flex-col gap-3">
                    <button
                      onClick={() => (inNotebook ? removeFromNotebook(selected.id) : addToNotebook(selected.id))}
                      className={`flex items-center justify-center gap-2 rounded-md px-4 py-2.5 text-sm font-medium transition-colors ${
                        inNotebook
                          ? 'bg-bronze text-paper-light hover:bg-bronze-dark'
                          : 'bg-cinnabar text-paper-light hover:bg-cinnabar-dark'
                      }`}
                    >
                      {inNotebook ? <BookmarkCheck size={16} /> : <Bookmark size={16} />}
                      {inNotebook ? '已收藏 · 点击移除' : '收藏到记录本'}
                    </button>
                    <button
                      onClick={() => addLearningRecord(selected.id, 'decoder', true)}
                      disabled={learned}
                      className={`flex items-center justify-center gap-2 rounded-md px-4 py-2.5 text-sm font-medium border transition-colors ${
                        learned
                          ? 'border-bronze/30 text-bronze-dark bg-bronze/5 cursor-default'
                          : 'border-cinnabar text-cinnabar hover:bg-cinnabar hover:text-paper-light'
                      }`}
                    >
                      <CheckCircle2 size={16} />
                      {learned ? '已标记已学' : '标记已学'}
                    </button>
                  </div>
                ) : (
                  <div className="rounded-md border border-gold/40 bg-gold/5 p-4 text-center">
                    <p className="text-sm text-ink-light mb-3">登录后可收藏字符、记录学习进度</p>
                    <Link
                      to="/auth"
                      className="inline-flex items-center gap-2 rounded-md bg-ink text-paper-light px-4 py-2 text-sm hover:bg-ink-light transition-colors"
                    >
                      <LogIn size={16} /> 立即登录 / 注册
                    </Link>
                  </div>
                )}
              </div>
            </div>
          </aside>
        </>
      )}
    </div>
  );
}
