import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import { useEffect } from "react";
import Navbar from "@/components/Navbar";
import AchievementToast from "@/components/AchievementToast";
import { useStore } from "@/store/useStore";
import Home from "@/pages/Home";
import Decoder from "@/pages/Decoder";
import Game from "@/pages/Game";
import Notebook from "@/pages/Notebook";
import NotebookDetail from "@/pages/NotebookDetail";
import Profile from "@/pages/Profile";
import Community from "@/pages/Community";
import Auth from "@/pages/Auth";

function ScrollToTop() {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
}

function AppLayout() {
  const user = useStore((s) => s.user);
  const loadUserData = useStore((s) => s.loadUserData);

  useEffect(() => {
    if (user) loadUserData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="min-h-screen flex flex-col paper-texture">
      <Navbar />
      <AchievementToast />
      <main className="flex-1 relative z-10">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/decoder" element={<Decoder />} />
          <Route path="/game" element={<Game />} />
          <Route path="/notebook" element={<Notebook />} />
          <Route path="/notebook/:charId" element={<NotebookDetail />} />
          <Route path="/profile" element={<Profile />} />
          <Route path="/community" element={<Community />} />
          <Route path="/auth" element={<Auth />} />
        </Routes>
      </main>
      <footer className="border-t border-ink-muted/20 bg-paper-dark/50 py-6 text-center text-sm text-ink-muted">
        <div className="font-xiaowei text-base text-ink-light">字从甲骨来</div>
        <div className="mt-1 text-xs">追溯汉字起源 · 探索象形之美 · 甲骨文象形互动探索平台</div>
      </footer>
    </div>
  );
}

export default function App() {
  return (
    <Router>
      <ScrollToTop />
      <AppLayout />
    </Router>
  );
}
