import { Link, useNavigate } from 'react-router-dom';
import { useMemo } from 'react';
import { useStore } from '@/store/useStore';
import { ORACLE_CHARS, CATEGORY_LABELS } from '@/data/oracleChars';
import { getPictoImage } from '@/data/oracleImages';
import { getLevelTitle } from '@/data/achievements';
import OracleGlyph from '@/components/OracleGlyph';
import ModeSwitcher from '@/components/ModeSwitcher';
import { BookOpen, Gamepad2, Flame, Notebook, ChevronRight, Sparkles, Calendar, Award } from 'lucide-react';

export default function Home() {
  const navigate = useNavigate();
  const user = useStore((s) => s.user);
  const learnedCharIds = useStore((s) => s.learnedCharIds);
  const streakDays = user?.streakDays ?? 0;
  const isCheckedInToday = useStore((s) => s.isCheckedInToday);
  const checkinToday = useStore((s) => s.checkinToday);

  // 今日一字（基于日期稳定随机）
  const todayChar = useMemo(() => {
    const dayOfYear = Math.floor(Date.now() / 86400000);
    return ORACLE_CHARS[dayOfYear % ORACLE_CHARS.length];
  }, []);

  const title = user ? getLevelTitle(user.exp) : null;
  const progress = Math.round((learnedCharIds.length / ORACLE_CHARS.length) * 100);
  const todayPicto = getPictoImage(todayChar.id);

  return (
    <div className="relative overflow-hidden">
      {/* ===== Hero 区 ===== */}
      <section className="relative min-h-[600px] flex items-center justify-center overflow-hidden">
        {/* 墨韵背景 */}
        <div className="absolute inset-0 -z-10">
          <div className="ink-blob bg-ink" style={{ width: 400, height: 400, top: '10%', left: '5%' }} />
          <div className="ink-blob bg-cinnabar" style={{ width: 300, height: 300, top: '50%', right: '10%' }} />
          <div className="ink-blob bg-bronze" style={{ width: 350, height: 350, bottom: '5%', left: '40%' }} />
          {/* 浮动甲骨文装饰 */}
          {ORACLE_CHARS.slice(0, 8).map((ch, i) => (
            <div
              key={ch.id}
              className="absolute animate-float-slow opacity-[0.08]"
              style={{
                top: `${[15, 25, 60, 70, 35, 80, 20, 55][i]}%`,
                left: `${[8, 85, 12, 88, 50, 25, 70, 45][i]}%`,
                animationDelay: `${i * 0.8}s`,
              }}
            >
              <OracleGlyph char={ch} size={[80, 60, 100, 70, 90, 55, 75, 85][i]} />
            </div>
          ))}
        </div>

        <div className="container mx-auto max-w-5xl px-4 py-20 text-center relative z-10">
          <div className="animate-fade-up" style={{ animationDelay: '0.1s' }}>
            <div className="inline-flex items-center gap-2 rounded-full border border-gold/40 bg-paper-light/60 px-4 py-1.5 text-sm text-gold-dark mb-6">
              <Sparkles size={14} />
              <span>甲骨文象形互动探索平台</span>
            </div>
          </div>

          <h1 className="font-brush text-7xl md:text-8xl text-ink mb-4 animate-fade-up" style={{ animationDelay: '0.2s' }}>
            字从甲骨来
          </h1>
          <p className="font-xiaowei text-xl md:text-2xl text-ink-light mb-2 animate-fade-up" style={{ animationDelay: '0.3s' }}>
            每一个汉字，都是一幅画
          </p>
          <p className="text-ink-muted max-w-2xl mx-auto mb-10 animate-fade-up" style={{ animationDelay: '0.4s' }}>
            追溯三千年前的龟甲契刻，在象形演变中读懂汉字的前世今生。
            解字、猜谜、记录、探索——开启你的甲骨文之旅。
          </p>

          {/* 双模式切换 */}
          <div className="flex flex-col items-center gap-6 animate-fade-up" style={{ animationDelay: '0.5s' }}>
            <ModeSwitcher size="lg" />
            <div className="flex flex-wrap justify-center gap-3">
              <Link
                to="/decoder"
                className="group flex items-center gap-3 rounded-lg border border-cinnabar/30 bg-cinnabar/5 px-5 py-3 hover:bg-cinnabar hover:text-paper-light transition-all"
              >
                <BookOpen size={20} className="text-cinnabar group-hover:text-paper-light" />
                <div className="text-left">
                  <div className="font-medium">解字器</div>
                  <div className="text-xs opacity-70">探索字形演变与造字故事</div>
                </div>
                <ChevronRight size={16} className="opacity-50 group-hover:translate-x-1 transition-transform" />
              </Link>
              <Link
                to="/game"
                className="group flex items-center gap-3 rounded-lg border border-bronze/30 bg-bronze/5 px-5 py-3 hover:bg-bronze hover:text-paper-light transition-all"
              >
                <Gamepad2 size={20} className="text-bronze group-hover:text-paper-light" />
                <div className="text-left">
                  <div className="font-medium">猜谜游戏</div>
                  <div className="text-xs opacity-70">看图识字，挑战连击</div>
                </div>
                <ChevronRight size={16} className="opacity-50 group-hover:translate-x-1 transition-transform" />
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* ===== 进度概览 ===== */}
      {user && (
        <section className="container mx-auto max-w-6xl px-4 py-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="ink-card rounded-xl p-5">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-ink-muted">已学甲骨文</span>
                <BookOpen size={18} className="text-cinnabar" />
              </div>
              <div className="font-xiaowei text-3xl text-ink">{learnedCharIds.length}<span className="text-base text-ink-muted">/{ORACLE_CHARS.length}</span></div>
              <div className="mt-2 h-1.5 rounded-full bg-paper-dark overflow-hidden">
                <div className="h-full bg-gradient-to-r from-cinnabar to-gold transition-all" style={{ width: `${progress}%` }} />
              </div>
            </div>
            <div className="ink-card rounded-xl p-5">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-ink-muted">连续打卡</span>
                <Flame size={18} className="text-cinnabar" />
              </div>
              <div className="font-xiaowei text-3xl text-ink">{streakDays}<span className="text-base text-ink-muted"> 天</span></div>
              <button
                onClick={() => isCheckedInToday ? null : checkinToday(todayChar.id)}
                disabled={isCheckedInToday}
                className={`mt-2 text-xs ${isCheckedInToday ? 'text-ink-muted' : 'text-cinnabar hover:underline'}`}
              >
                {isCheckedInToday ? '今日已打卡 ✓' : '点击打卡 →'}
              </button>
            </div>
            <div className="ink-card rounded-xl p-5">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-ink-muted">当前等级</span>
                <Award size={18} className="text-gold-dark" />
              </div>
              <div className="font-xiaowei text-3xl" style={{ color: title?.color }}>Lv.{user.level}</div>
              <div className="mt-2 text-xs text-ink-muted">{title?.title} · 经验 {user.exp}</div>
            </div>
            <div className="ink-card rounded-xl p-5">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-ink-muted">记录本</span>
                <Notebook size={18} className="text-bronze" />
              </div>
              <div className="font-xiaowei text-3xl text-ink">{useStore.getState().notebookEntries.length}<span className="text-base text-ink-muted"> 条</span></div>
              <Link to="/notebook" className="mt-2 inline-block text-xs text-bronze hover:underline">查看记录 →</Link>
            </div>
          </div>
        </section>
      )}

      {/* ===== 今日一字 ===== */}
      <section className="container mx-auto max-w-5xl px-4 py-12">
        <div className="text-center mb-8">
          <h2 className="font-xiaowei text-3xl text-ink mb-1">今日一字</h2>
          <p className="text-sm text-ink-muted">每日一甲骨，积少成多</p>
        </div>
        <div className="ink-card rounded-2xl p-8 md:p-12 relative overflow-hidden">
          <div className="absolute top-4 right-4 seal-stamp px-3 py-1 text-sm">今日推荐</div>
          <div className="grid md:grid-cols-2 gap-8 items-center">
            <div className="flex flex-col items-center">
              <div className="flex items-center gap-4">
                {/* 甲骨文 */}
                <div className="flex flex-col items-center">
                  <div className="rounded-xl bg-paper p-5 border border-ink-muted/20">
                    <OracleGlyph char={todayChar} size={140} animated />
                  </div>
                  <span className="mt-2 text-xs text-ink-muted">甲骨文</span>
                </div>
                {/* 现实事物图片 */}
                {todayPicto && (
                  <div className="flex flex-col items-center">
                    <div className="h-[180px] w-[180px] rounded-xl overflow-hidden border border-ink-muted/20 bg-paper-dark">
                      <img
                        src={todayPicto.imageUrl}
                        alt={`${todayChar.modernChar}象形参考`}
                        className="h-full w-full object-cover"
                        loading="lazy"
                      />
                    </div>
                    <span className="mt-2 text-xs text-ink-muted">象形之源</span>
                  </div>
                )}
              </div>
              <div className="mt-4 flex items-baseline gap-3">
                <span className="font-serif text-5xl text-ink">{todayChar.modernChar}</span>
                <span className="text-ink-muted">{todayChar.pinyin}</span>
              </div>
              <span className="mt-1 text-xs px-2 py-0.5 rounded bg-bronze/15 text-bronze-dark">{CATEGORY_LABELS[todayChar.category]}</span>
            </div>
            <div>
              <h3 className="font-xiaowei text-2xl text-ink mb-3">造字故事</h3>
              <p className="text-ink-light leading-relaxed mb-4">{todayChar.story}</p>
              <p className="text-sm text-ink-muted italic border-l-2 border-gold pl-3">{todayChar.meaning}</p>
              <div className="mt-6 flex gap-3">
                <button
                  onClick={() => navigate('/decoder')}
                  className="flex items-center gap-1.5 rounded-md bg-cinnabar px-4 py-2 text-sm text-paper-light hover:bg-cinnabar-dark transition-colors"
                >
                  <BookOpen size={16} />
                  深入学习
                </button>
                <button
                  onClick={() => navigate('/game')}
                  className="flex items-center gap-1.5 rounded-md border border-bronze px-4 py-2 text-sm text-bronze hover:bg-bronze hover:text-paper-light transition-colors"
                >
                  <Gamepad2 size={16} />
                  猜谜挑战
                </button>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* ===== 字库速览 ===== */}
      <section className="container mx-auto max-w-7xl px-4 py-12">
        <div className="flex items-end justify-between mb-6">
          <div>
            <h2 className="font-xiaowei text-3xl text-ink mb-1">字库速览</h2>
            <p className="text-sm text-ink-muted">精选 {ORACLE_CHARS.length} 个甲骨文，点击进入解字器</p>
          </div>
          <Link to="/decoder" className="flex items-center gap-1 text-sm text-cinnabar hover:underline">
            查看全部 <ChevronRight size={16} />
          </Link>
        </div>
        <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-12 gap-3">
          {ORACLE_CHARS.map((ch) => {
            const learned = learnedCharIds.includes(ch.id);
            return (
              <Link
                key={ch.id}
                to="/decoder"
                className="group relative flex flex-col items-center rounded-lg border border-ink-muted/20 bg-paper-light p-3 hover:border-cinnabar/40 hover:shadow-md transition-all"
              >
                {learned && (
                  <span className="absolute top-1 right-1 h-2 w-2 rounded-full bg-bronze" title="已学习" />
                )}
                <OracleGlyph char={ch} size={48} color="#3D3833" />
                <span className="mt-1 font-serif text-lg text-ink group-hover:text-cinnabar transition-colors">{ch.modernChar}</span>
              </Link>
            );
          })}
        </div>
      </section>

      {/* ===== 快捷入口 ===== */}
      <section className="container mx-auto max-w-5xl px-4 py-12">
        <div className="grid sm:grid-cols-3 gap-4">
          <Link to="/notebook" className="ink-card rounded-xl p-6 group">
            <Notebook className="text-bronze mb-3" size={28} />
            <h3 className="font-xiaowei text-xl text-ink mb-1">记录本</h3>
            <p className="text-sm text-ink-muted">收藏学过的甲骨文，记录演变与故事</p>
          </Link>
          <Link to="/community" className="ink-card rounded-xl p-6 group">
            <Calendar className="text-cinnabar mb-3" size={28} />
            <h3 className="font-xiaowei text-xl text-ink mb-1">社区打卡</h3>
            <p className="text-sm text-ink-muted">每日打卡，与同好交流学习心得</p>
          </Link>
          <Link to="/profile" className="ink-card rounded-xl p-6 group">
            <Award className="text-gold-dark mb-3" size={28} />
            <h3 className="font-xiaowei text-xl text-ink mb-1">成就系统</h3>
            <p className="text-sm text-ink-muted">解锁徽章，记录你的甲骨文之旅</p>
          </Link>
        </div>
      </section>
    </div>
  );
}
