export const LEVEL_TITLES = [
  { min: 0, title: '蒙童', color: '#8B8378' },
  { min: 5, title: '学童', color: '#5C7A6F' },
  { min: 12, title: '塾师', color: '#C9A961' },
  { min: 20, title: '翰林', color: '#B33A2A' },
  { min: 30, title: '甲骨宗师', color: '#8C2A1E' },
];

export function getLevelTitle(exp: number) {
  let result = LEVEL_TITLES[0];
  for (const item of LEVEL_TITLES) {
    if (exp >= item.min) result = item;
  }
  return result;
}

export function getLevelFromExp(exp: number) {
  return Math.floor(exp / 10) + 1;
}
