import { Link, useNavigate } from 'react-router-dom';
import { useStore } from '@/store/useStore';
import { getCharById, CATEGORY_LABELS } from '@/data/oracleChars';
import OracleGlyph from '@/components/OracleGlyph';
import { Notebook as NotebookIcon, Trash2, BookOpen, LogIn } from 'lucide-react';

export default function NotebookPage() {
  const navigate = useNavigate();
  const user = useStore((s) => s.user);
  const notebookEntries = useStore((s) => s.notebookEntries);
  const removeFromNotebook = useStore((s) => s.removeFromNotebook);

  // 未登录
  if (!user) {
    return (
      <div className="container mx-auto max-w-md px-4 py-20">
        <div className="ink-card rounded-2xl p-10 text-center">
          <NotebookIcon size={56} className="mx-auto text-bronze mb-4" />
          <h1 className="font-xiaowei text-2xl text-ink mb-2">记录本</h1>
          <p className="text-ink-muted mb-6">登录后即可收藏甲骨文，记录你的学习心得</p>
          <Link
            to="/auth"
            className="inline-flex items-center gap-2 rounded-md bg-cinnabar px-5 py-2.5 text-paper-light hover:bg-cinnabar-dark transition-colors"
          >
            <LogIn size={18} />
            登录 / 注册
          </Link>
        </div>
      </div>
    );
  }

  // 已登录但记录本为空
  if (notebookEntries.length === 0) {
    return (
      <div className="container mx-auto max-w-md px-4 py-20">
        <div className="ink-card rounded-2xl p-10 text-center">
          <div className="font-brush text-8xl text-ink-muted/30 mb-4">零</div>
          <h1 className="font-xiaowei text-2xl text-ink mb-2">记录本还是空的</h1>
          <p className="text-ink-muted mb-6">去解字器收藏一些甲骨文吧</p>
          <Link
            to="/decoder"
            className="inline-flex items-center gap-2 rounded-md bg-cinnabar px-5 py-2.5 text-paper-light hover:bg-cinnabar-dark transition-colors"
          >
            <BookOpen size={18} />
            前往解字器
          </Link>
        </div>
      </div>
    );
  }

  // 分类分布统计
  const categoryCount: Record<string, number> = {};
  notebookEntries.forEach((entry) => {
    const ch = getCharById(entry.charId);
    if (ch) categoryCount[ch.category] = (categoryCount[ch.category] || 0) + 1;
  });

  const formatDate = (ts: number) => new Date(ts).toISOString().slice(0, 10);

  return (
    <div className="container mx-auto max-w-7xl px-4 py-10">
      {/* 标题 */}
      <div className="mb-8 text-center">
        <h1 className="font-brush text-5xl text-ink mb-2">记录本</h1>
        <p className="font-xiaowei text-lg text-ink-muted">我收藏的甲骨文</p>
      </div>

      {/* 汇总栏 */}
      <div className="ink-card rounded-xl p-5 mb-8">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2">
            <NotebookIcon size={20} className="text-bronze" />
            <span className="font-xiaowei text-xl text-ink">{notebookEntries.length}</span>
            <span className="text-sm text-ink-muted">条收藏</span>
          </div>
          <div className="hidden sm:block h-6 w-px bg-ink-muted/30" />
          <div className="flex flex-wrap gap-2">
            {Object.entries(categoryCount).map(([cat, count]) => (
              <span
                key={cat}
                className="inline-flex items-center gap-1 rounded-full bg-bronze/10 px-3 py-1 text-xs text-bronze-dark"
              >
                {CATEGORY_LABELS[cat]} · {count}
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* 卡片墙 */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {notebookEntries.map((entry) => {
          const ch = getCharById(entry.charId);
          if (!ch) return null;
          const notePreview = entry.note
            ? entry.note.length > 30
              ? entry.note.slice(0, 30) + '…'
              : entry.note
            : '暂无笔记';
          return (
            <div
              key={entry.id}
              className="ink-card rounded-xl p-4 relative group cursor-pointer"
              onClick={() => navigate(`/notebook/${entry.charId}`)}
            >
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  removeFromNotebook(entry.charId);
                }}
                className="absolute top-2 right-2 p-1.5 rounded-md text-ink-muted hover:bg-cinnabar/10 hover:text-cinnabar opacity-0 group-hover:opacity-100 transition-opacity"
                title="删除"
              >
                <Trash2 size={16} />
              </button>
              <div className="flex flex-col items-center">
                <div className="rounded-lg bg-paper p-3 border border-ink-muted/20">
                  <OracleGlyph char={ch} size={80} />
                </div>
                <div className="mt-3 flex items-baseline gap-2">
                  <span className="font-serif text-3xl text-ink">{ch.modernChar}</span>
                  <span className="text-sm text-ink-muted">{ch.pinyin}</span>
                </div>
                <span className="mt-1 text-xs px-2 py-0.5 rounded bg-bronze/15 text-bronze-dark">
                  {CATEGORY_LABELS[ch.category]}
                </span>
                <span className="mt-2 text-xs text-ink-muted">收藏于 {formatDate(entry.addedAt)}</span>
                <p className="mt-2 text-xs text-ink-light text-center line-clamp-2 w-full">
                  {notePreview}
                </p>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
