export const CATEGORY_LABELS: Record<string, string> = {
  nature: '天地自然',
  body: '人体形态',
  animal: '飞禽走兽',
  object: '器物文明',
};

export function getCharById(id: string): OracleChar | undefined {
  return ORACLE_CHARS.find((c) => c.id === id);
}

export function getRandomChar(): OracleChar {
  return ORACLE_CHARS[Math.floor(Math.random() * ORACLE_CHARS.length)];
}
