import { useNavigate } from 'react-router-dom';
import { useStore } from '@/store/useStore';
import { BookOpen, Gamepad2 } from 'lucide-react';
import type { LearnMode } from '@/types';

// 两种学习模式随时可切换的切换器
export default function ModeSwitcher({
  className = '',
  size = 'md',
}: {
  className?: string;
  size?: 'sm' | 'md' | 'lg';
}) {
  const navigate = useNavigate();
  const currentMode = useStore((s) => s.currentMode);
  const setMode = useStore((s) => s.setMode);

  const sizes = {
    sm: { btn: 'px-3 py-1.5 text-xs', icon: 14 },
    md: { btn: 'px-4 py-2 text-sm', icon: 16 },
    lg: { btn: 'px-6 py-3 text-base', icon: 20 },
  };

  const handleSwitch = (mode: LearnMode) => {
    setMode(mode);
    if (mode === 'decoder') navigate('/decoder');
    else navigate('/game');
  };

  return (
    <div className={`inline-flex items-center rounded-lg border border-ink-muted/30 bg-paper-light p-1 ${className}`}>
      <button
        onClick={() => handleSwitch('decoder')}
        className={`flex items-center gap-2 rounded-md font-medium transition-all ${sizes[size].btn} ${
          currentMode === 'decoder'
            ? 'bg-cinnabar text-paper-light shadow-md'
            : 'text-ink-muted hover:text-ink'
        }`}
      >
        <BookOpen size={sizes[size].icon} />
        <span>解字器</span>
      </button>
      <button
        onClick={() => handleSwitch('game')}
        className={`flex items-center gap-2 rounded-md font-medium transition-all ${sizes[size].btn} ${
          currentMode === 'game'
            ? 'bg-bronze text-paper-light shadow-md'
            : 'text-ink-muted hover:text-ink'
        }`}
      >
        <Gamepad2 size={sizes[size].icon} />
        <span>猜谜游戏</span>
      </button>
    </div>
  );
}
