import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useStore } from '@/store/useStore';
import { User, Lock, LogIn, UserPlus, Eye, EyeOff } from 'lucide-react';

export default function Auth() {
  const navigate = useNavigate();
  const login = useStore((s) => s.login);
  const register = useStore((s) => s.register);

  const [tab, setTab] = useState<'login' | 'register'>('login');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const [showPwd, setShowPwd] = useState(false);

  const handleLogin = () => {
    setError('');
    if (username.trim().length < 2) { setError('用户名至少 2 个字符'); return; }
    if (password.length < 4) { setError('密码至少 4 位'); return; }
    const res = login(username.trim(), password);
    if (!res.success) { setError(res.message); return; }
    navigate('/');
  };

  const handleRegister = () => {
    setError('');
    if (username.trim().length < 2) { setError('用户名至少 2 个字符'); return; }
    if (password.length < 4) { setError('密码至少 4 位'); return; }
    if (password !== confirm) { setError('两次输入的密码不一致'); return; }
    const res = register(username.trim(), password);
    if (!res.success) { setError(res.message); return; }
    navigate('/');
  };

  return (
    <div className="min-h-[calc(100vh-4rem)] flex items-center justify-center px-4 py-12">
      <div className="w-full max-w-md">
        {/* 印章标题 */}
        <div className="text-center mb-8">
          <div className="seal-stamp inline-block px-6 py-3 text-3xl animate-seal-stamp">
            字从甲骨来
          </div>
          <p className="mt-4 text-sm text-ink-muted">追溯汉字起源 · 探索象形之美</p>
        </div>

        <div className="ink-card rounded-2xl p-6 md:p-8">
          {/* Tab 切换 */}
          <div className="flex border-b border-ink-muted/20 mb-6">
            <button
              onClick={() => { setTab('login'); setError(''); }}
              className={`flex-1 flex items-center justify-center gap-1.5 pb-3 text-sm font-medium transition-colors ${
                tab === 'login'
                  ? 'text-cinnabar border-b-2 border-cinnabar'
                  : 'text-ink-muted hover:text-ink'
              }`}
            >
              <LogIn size={16} /> 登录
            </button>
            <button
              onClick={() => { setTab('register'); setError(''); }}
              className={`flex-1 flex items-center justify-center gap-1.5 pb-3 text-sm font-medium transition-colors ${
                tab === 'register'
                  ? 'text-cinnabar border-b-2 border-cinnabar'
                  : 'text-ink-muted hover:text-ink'
              }`}
            >
              <UserPlus size={16} /> 注册
            </button>
          </div>

          {/* 表单 */}
          <div className="space-y-4">
            <div>
              <label className="block text-xs text-ink-muted mb-1.5">用户名</label>
              <div className="relative">
                <User size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-ink-muted" />
                <input
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="至少 2 个字符"
                  className="w-full rounded-lg bg-paper-light border border-ink-muted/20 pl-9 pr-3 py-2.5 text-sm text-ink focus:outline-none focus:border-cinnabar/40"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs text-ink-muted mb-1.5">密码</label>
              <div className="relative">
                <Lock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-ink-muted" />
                <input
                  type={showPwd ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="至少 4 位"
                  className="w-full rounded-lg bg-paper-light border border-ink-muted/20 pl-9 pr-9 py-2.5 text-sm text-ink focus:outline-none focus:border-cinnabar/40"
                />
                <button
                  type="button"
                  onClick={() => setShowPwd(!showPwd)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted hover:text-ink"
                >
                  {showPwd ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>

            {tab === 'register' && (
              <div>
                <label className="block text-xs text-ink-muted mb-1.5">确认密码</label>
                <div className="relative">
                  <Lock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-ink-muted" />
                  <input
                    type={showPwd ? 'text' : 'password'}
                    value={confirm}
                    onChange={(e) => setConfirm(e.target.value)}
                    placeholder="再次输入密码"
                    className="w-full rounded-lg bg-paper-light border border-ink-muted/20 pl-9 pr-3 py-2.5 text-sm text-ink focus:outline-none focus:border-cinnabar/40"
                  />
                </div>
              </div>
            )}

            {error && (
              <div className="rounded-lg bg-cinnabar/10 border border-cinnabar/20 px-3 py-2 text-sm text-cinnabar">
                {error}
              </div>
            )}

            <button
              onClick={tab === 'login' ? handleLogin : handleRegister}
              className="w-full flex items-center justify-center gap-2 rounded-lg bg-cinnabar px-4 py-2.5 text-paper-light font-medium hover:bg-cinnabar-dark transition-colors"
            >
              {tab === 'login' ? <LogIn size={16} /> : <UserPlus size={16} />}
              {tab === 'login' ? '登录' : '注册'}
            </button>
          </div>

          <div className="mt-6 text-center text-sm text-ink-muted">
            <Link to="/" className="hover:text-cinnabar transition-colors">
              游客访问 →
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}
