import { useState, useMemo } from 'react';
import { useStore } from '@/store/useStore';
import { getCharById } from '@/data/oracleChars';
import OracleGlyph from '@/components/OracleGlyph';
import { Heart, MessageCircle, Send, TrendingUp, Crown, Medal } from 'lucide-react';

function timeAgo(ts: number) {
  const diff = Date.now() - ts;
  if (diff < 60000) return '刚刚';
  if (diff < 3600000) return `${Math.floor(diff / 60000)}分钟前`;
  if (diff < 86400000) return `${Math.floor(diff / 3600000)}小时前`;
  return `${Math.floor(diff / 86400000)}天前`;
}

const TYPE_BADGE: Record<string, { label: string; cls: string }> = {
  checkin: { label: '打卡', cls: 'bg-bronze/15 text-bronze-dark' },
  learn: { label: '学习', cls: 'bg-cinnabar/15 text-cinnabar' },
  achievement: { label: '成就', cls: 'bg-gold/20 text-gold-dark' },
};

const RANK_STYLES = [
  { icon: Crown, cls: 'text-gold-dark' },
  { icon: Medal, cls: 'text-ink-muted' },
  { icon: Medal, cls: 'text-bronze' },
];

export default function Community() {
  const user = useStore((s) => s.user);
  const communityPosts = useStore((s) => s.communityPosts);
  const addCommunityPost = useStore((s) => s.addCommunityPost);
  const likePost = useStore((s) => s.likePost);
  const addComment = useStore((s) => s.addComment);

  const [newPost, setNewPost] = useState('');
  const [commentInputs, setCommentInputs] = useState<Record<string, string>>({});

  const sortedPosts = useMemo(
    () => [...communityPosts].sort((a, b) => b.createdAt - a.createdAt),
    [communityPosts],
  );

  // 排行榜：按获赞数
  const ranking = useMemo(() => {
    const map = new Map<string, { userId: string; username: string; avatar: string; likes: number; posts: number }>();
    communityPosts.forEach((p) => {
      const cur = map.get(p.userId) || { userId: p.userId, username: p.username, avatar: p.avatar, likes: 0, posts: 0 };
      cur.likes += p.likes;
      cur.posts += 1;
      map.set(p.userId, cur);
    });
    return [...map.values()].sort((a, b) => b.likes - a.likes).slice(0, 5);
  }, [communityPosts]);

  const handlePost = () => {
    if (!newPost.trim()) return;
    addCommunityPost({ type: 'learn', content: newPost.trim() });
    setNewPost('');
  };

  const handleComment = (postId: string) => {
    const content = (commentInputs[postId] || '').trim();
    if (!content) return;
    addComment(postId, content);
    setCommentInputs({ ...commentInputs, [postId]: '' });
  };

  return (
    <div className="container mx-auto max-w-6xl px-4 py-8">
      <div className="grid lg:grid-cols-[1fr_320px] gap-6">
        {/* ===== 动态流 ===== */}
        <div className="space-y-5">
          <h1 className="font-xiaowei text-3xl text-ink">社区广场</h1>

          {user && (
            <div className="ink-card rounded-xl p-4">
              <textarea
                value={newPost}
                onChange={(e) => setNewPost(e.target.value)}
                placeholder="分享你的学习心得……"
                rows={3}
                className="w-full resize-none rounded-lg bg-paper-light border border-ink-muted/20 p-3 text-sm text-ink focus:outline-none focus:border-cinnabar/40"
              />
              <div className="flex justify-end mt-2">
                <button
                  onClick={handlePost}
                  disabled={!newPost.trim()}
                  className="flex items-center gap-1.5 rounded-md bg-cinnabar px-4 py-1.5 text-sm text-paper-light hover:bg-cinnabar-dark disabled:opacity-40 transition-colors"
                >
                  <Send size={14} /> 发布
                </button>
              </div>
            </div>
          )}

          {sortedPosts.map((post) => {
            const badge = TYPE_BADGE[post.type] || TYPE_BADGE.learn;
            const charObj = post.charId ? getCharById(post.charId) : undefined;
            const liked = user ? post.likedBy.includes(user.id) : false;
            return (
              <div key={post.id} className="ink-card rounded-xl p-4">
                <div className="flex items-start gap-3">
                  <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-bronze text-paper-light font-medium">
                    {post.avatar}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-medium text-ink">{post.username}</span>
                      <span className={`text-xs px-1.5 py-0.5 rounded ${badge.cls}`}>{badge.label}</span>
                      <span className="text-xs text-ink-muted">{timeAgo(post.createdAt)}</span>
                    </div>
                    <p className="text-sm text-ink-light mt-1.5 leading-relaxed whitespace-pre-wrap">{post.content}</p>
                    {charObj && (
                      <div className="mt-2 inline-flex items-center gap-2 rounded-lg bg-paper border border-ink-muted/20 px-3 py-1.5">
                        <OracleGlyph char={charObj} size={32} color="#3D3833" />
                        <span className="font-serif text-lg text-ink">{charObj.modernChar}</span>
                        {post.charName && <span className="text-xs text-ink-muted">· {post.charName}</span>}
                      </div>
                    )}
                    <div className="flex items-center gap-4 mt-3">
                      <button
                        onClick={() => likePost(post.id)}
                        disabled={!user}
                        className={`flex items-center gap-1 text-sm transition-colors ${
                          liked ? 'text-cinnabar' : 'text-ink-muted hover:text-cinnabar'
                        } disabled:opacity-40`}
                      >
                        <Heart size={16} fill={liked ? 'currentColor' : 'none'} />
                        <span>{post.likes}</span>
                      </button>
                      <span className="flex items-center gap-1 text-sm text-ink-muted">
                        <MessageCircle size={16} /> {post.comments.length}
                      </span>
                    </div>

                    {/* 评论 */}
                    {post.comments.length > 0 && (
                      <div className="mt-3 space-y-2 border-l-2 border-paper-dark pl-3">
                        {post.comments.map((c) => (
                          <div key={c.id} className="flex items-start gap-2">
                            <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-bronze/70 text-paper-light text-xs">
                              {c.avatar}
                            </div>
                            <div className="text-sm">
                              <span className="font-medium text-ink">{c.username}：</span>
                              <span className="text-ink-light">{c.content}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}

                    {user && (
                      <div className="flex items-center gap-2 mt-2">
                        <input
                          value={commentInputs[post.id] || ''}
                          onChange={(e) => setCommentInputs({ ...commentInputs, [post.id]: e.target.value })}
                          onKeyDown={(e) => e.key === 'Enter' && handleComment(post.id)}
                          placeholder="写评论…"
                          className="flex-1 rounded-md bg-paper-light border border-ink-muted/20 px-2.5 py-1 text-sm focus:outline-none focus:border-cinnabar/40"
                        />
                        <button
                          onClick={() => handleComment(post.id)}
                          className="rounded-md p-1.5 text-ink-muted hover:text-cinnabar hover:bg-cinnabar/10 transition-colors"
                        >
                          <Send size={14} />
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* ===== 排行榜 ===== */}
        <aside className="space-y-4">
          <div className="ink-card rounded-xl p-5 lg:sticky lg:top-20">
            <h2 className="font-xiaowei text-xl text-ink mb-4 flex items-center gap-2">
              <TrendingUp className="text-cinnabar" size={18} /> 本周排行
            </h2>
            <div className="space-y-3">
              {ranking.map((r, i) => {
                const RankIcon = RANK_STYLES[i]?.icon;
                const isMe = user && r.userId === user.id;
                return (
                  <div
                    key={r.userId}
                    className={`flex items-center gap-3 rounded-lg p-2 ${
                      isMe ? 'bg-cinnabar/10 border border-cinnabar/20' : ''
                    }`}
                  >
                    <div className={`w-6 text-center font-xiaowei ${RANK_STYLES[i]?.cls || 'text-ink-muted'}`}>
                      {RankIcon ? <RankIcon size={18} className="mx-auto" /> : i + 1}
                    </div>
                    <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-bronze text-paper-light text-sm">
                      {r.avatar}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-medium text-ink truncate">
                        {r.username}{isMe && <span className="text-xs text-cinnabar"> (我)</span>}
                      </div>
                      <div className="text-xs text-ink-muted">{r.posts} 动态 · {r.likes} 赞</div>
                    </div>
                    {i < 3 && (
                      <span className="font-xiaowei text-sm" style={{ color: RANK_STYLES[i].cls.includes('gold') ? '#A8893F' : undefined }}>
                        {i === 0 ? '榜首' : ''}
                      </span>
                    )}
                  </div>
                );
              })}
              {ranking.length === 0 && (
                <p className="text-sm text-ink-muted text-center py-4">暂无排行数据</p>
              )}
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}
