import { useEffect } from 'react';
import { useStore } from '@/store/useStore';
import { ACHIEVEMENTS } from '@/data/achievements';
import * as LucideIcons from 'lucide-react';
import { X, Sparkles } from 'lucide-react';

// 成就解锁弹窗
export default function AchievementToast() {
  const newlyUnlocked = useStore((s) => s.newlyUnlocked);
  const clearNewlyUnlocked = useStore((s) => s.clearNewlyUnlocked);

  useEffect(() => {
    if (newlyUnlocked) {
      const timer = setTimeout(() => clearNewlyUnlocked(), 5000);
      return () => clearTimeout(timer);
    }
  }, [newlyUnlocked, clearNewlyUnlocked]);

  if (!newlyUnlocked) return null;
  const achievement = ACHIEVEMENTS.find((a) => a.id === newlyUnlocked);
  if (!achievement) return null;

  const IconComponent = (LucideIcons as unknown as Record<string, React.ComponentType<{ size?: number; className?: string }>>)[achievement.icon] || Sparkles;

  return (
    <div className="fixed top-20 right-4 z-[100] animate-seal-stamp">
      <div className="relative flex items-center gap-4 rounded-lg border-2 border-gold bg-paper-light p-4 shadow-2xl gold-glow max-w-sm">
        <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-gold to-gold-dark text-paper-light">
          <IconComponent size={28} />
        </div>
        <div className="flex-1">
          <div className="flex items-center gap-1.5 text-xs text-gold-dark font-medium">
            <Sparkles size={12} />
            <span>成就解锁</span>
          </div>
          <div className="font-xiaowei text-lg text-ink leading-tight">{achievement.name}</div>
          <div className="text-xs text-ink-muted mt-0.5">{achievement.description}</div>
        </div>
        <button
          onClick={clearNewlyUnlocked}
          className="absolute -top-2 -right-2 flex h-6 w-6 items-center justify-center rounded-full bg-ink text-paper-light hover:bg-cinnabar transition-colors"
        >
          <X size={14} />
        </button>
      </div>
    </div>
  );
}
