import { useState } from 'react';
import type { OracleChar } from '@/types';
import { getPictoImage } from '@/data/oracleImages';
import OracleGlyph from '@/components/OracleGlyph';
import { ImageIcon, Eye, ArrowRight } from 'lucide-react';

interface PictoCompareProps {
  char: OracleChar;
}

// 象形对照组件：展示甲骨文与现实事物的对照
export default function PictoCompare({ char }: PictoCompareProps) {
  const picto = getPictoImage(char.id);
  const [imgLoaded, setImgLoaded] = useState(false);
  const [imgError, setImgError] = useState(false);

  if (!picto) return null;

  return (
    <div>
      <h3 className="font-xiaowei text-lg text-ink mb-3 flex items-center gap-2">
        <Eye size={16} className="text-cinnabar" /> 象形对照
      </h3>

      {/* 对照展示：甲骨文 → 现实事物 */}
      <div className="rounded-xl border border-ink-muted/20 bg-paper p-4">
        <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-3">
          {/* 左：甲骨文 */}
          <div className="flex flex-col items-center">
            <div className="h-28 w-28 flex items-center justify-center rounded-lg bg-paper-light border border-ink-muted/15">
              <OracleGlyph char={char} size={90} color="#1A1814" />
            </div>
            <span className="mt-2 text-xs text-ink-muted">甲骨文</span>
          </div>

          {/* 中：箭头 */}
          <div className="flex flex-col items-center px-1">
            <ArrowRight size={24} className="text-gold-dark" />
            <span className="mt-1 text-[10px] text-ink-muted whitespace-nowrap">象形</span>
          </div>

          {/* 右：现实图片 */}
          <div className="flex flex-col items-center">
            <div className="h-28 w-28 relative rounded-lg overflow-hidden border border-ink-muted/15 bg-paper-dark">
              {!imgLoaded && !imgError && (
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="h-8 w-8 border-2 border-ink-muted/30 border-t-cinnabar rounded-full animate-spin" />
                </div>
              )}
              {imgError ? (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-ink-muted">
                  <ImageIcon size={24} className="opacity-40" />
                  <span className="mt-1 text-[10px]">图片加载失败</span>
                </div>
              ) : (
                <img
                  src={picto.imageUrl}
                  alt={`${char.modernChar}的象形参考`}
                  className={`h-full w-full object-cover transition-opacity duration-500 ${imgLoaded ? 'opacity-100' : 'opacity-0'}`}
                  onLoad={() => setImgLoaded(true)}
                  onError={() => setImgError(true)}
                />
              )}
            </div>
            <span className="mt-2 text-xs text-ink-muted">现实事物</span>
          </div>
        </div>

        {/* 图注 */}
        <p className="mt-3 text-xs text-ink-light leading-relaxed border-l-2 border-gold pl-3 italic">
          {picto.caption}
        </p>
      </div>
    </div>
  );
}
