import { useParams, useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { useStore } from '@/store/useStore';
import { getCharById, CATEGORY_LABELS } from '@/data/oracleChars';
import OracleGlyph, { EvolutionGlyph } from '@/components/OracleGlyph';
import { ArrowLeft, Trash2, Save, BookOpen, Notebook as NotebookIcon } from 'lucide-react';

const STAGE_DESC: Record<string, string> = {
  oracle: '商代·龟甲兽骨契刻',
  bronze: '西周·青铜器铭文',
  seal: '秦代·统一文字',
  clerical: '汉代·隶变',
  regular: '魏晋至今·楷书',
};

export default function NotebookDetail() {
  const { charId } = useParams<{ charId: string }>();
  const navigate = useNavigate();

  const notebookEntries = useStore((s) => s.notebookEntries);
  const removeFromNotebook = useStore((s) => s.removeFromNotebook);
  const updateNote = useStore((s) => s.updateNote);

  const char = charId ? getCharById(charId) : undefined;
  const entry = notebookEntries.find((e) => e.charId === charId);

  const [note, setNote] = useState(entry?.note || '');
  const [saved, setSaved] = useState(false);

  // 切换字符时同步笔记
  useEffect(() => {
    const e = notebookEntries.find((en) => en.charId === charId);
    setNote(e?.note || '');
    setSaved(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [charId]);

  if (!char || !entry) {
    return (
      <div className="container mx-auto max-w-md px-4 py-20 text-center">
        <p className="text-ink-muted mb-4">未找到该记录</p>
        <button
          onClick={() => navigate('/notebook')}
          className="inline-flex items-center gap-2 rounded-md bg-cinnabar px-5 py-2 text-paper-light hover:bg-cinnabar-dark transition-colors"
        >
          <ArrowLeft size={16} />
          返回记录本
        </button>
      </div>
    );
  }

  const handleSave = () => {
    updateNote(char.id, note);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const handleDelete = () => {
    removeFromNotebook(char.id);
    navigate('/notebook');
  };

  return (
    <div className="container mx-auto max-w-6xl px-4 py-8">
      {/* 返回按钮 */}
      <button
        onClick={() => navigate('/notebook')}
        className="inline-flex items-center gap-2 text-ink-muted hover:text-ink transition-colors mb-6"
      >
        <ArrowLeft size={18} />
        返回记录本
      </button>

      <div className="grid md:grid-cols-2 gap-8">
        {/* 左栏：字形展示 */}
        <div className="ink-card rounded-2xl p-8">
          <div className="flex flex-col items-center">
            <div className="rounded-xl bg-paper p-6 border border-ink-muted/20 gold-glow">
              <OracleGlyph char={char} size={200} animated />
            </div>
            <div className="mt-5 flex items-baseline gap-3">
              <span className="font-serif text-6xl text-ink">{char.modernChar}</span>
              <span className="text-lg text-ink-muted">{char.pinyin}</span>
            </div>
            <div className="mt-3 flex flex-wrap gap-2 justify-center">
              <span className="px-3 py-1 rounded-full bg-bronze/15 text-bronze-dark text-sm">
                {CATEGORY_LABELS[char.category]}
              </span>
              <span className="px-3 py-1 rounded-full bg-paper-dark text-ink-light text-sm">
                部首：{char.radical}
              </span>
            </div>
            <p className="mt-5 text-sm text-ink-light italic border-l-2 border-gold pl-4 text-left w-full">
              {char.meaning}
            </p>
          </div>
        </div>

        {/* 右栏：故事、演变、笔记 */}
        <div className="space-y-6">
          {/* 造字故事 */}
          <div className="ink-card rounded-2xl p-6">
            <h2 className="font-xiaowei text-xl text-ink mb-3 flex items-center gap-2">
              <BookOpen size={20} className="text-cinnabar" />
              造字故事
            </h2>
            <div className="border-l-4 border-gold pl-4 py-1">
              <p className="text-ink-light leading-relaxed">{char.story}</p>
            </div>
          </div>

          {/* 字形演变时间线 */}
          <div className="ink-card rounded-2xl p-6">
            <h2 className="font-xiaowei text-xl text-ink mb-4 flex items-center gap-2">
              <NotebookIcon size={20} className="text-bronze" />
              字形演变
            </h2>
            <div className="relative pl-6">
              {char.evolution.map((form, idx) => (
                <div key={form.stage} className="relative pb-6 last:pb-0">
                  {idx < char.evolution.length - 1 && (
                    <span className="absolute left-[-14px] top-4 bottom-0 w-px bg-ink-muted/30" />
                  )}
                  <span className="absolute left-[-18px] top-1.5 h-3 w-3 rounded-full bg-cinnabar border-2 border-paper-light" />
                  <div className="flex items-center gap-4">
                    <div
                      className="rounded-md bg-paper p-2 border border-ink-muted/20 flex items-center justify-center"
                      style={{ minWidth: 80, minHeight: 80 }}
                    >
                      <EvolutionGlyph form={form} modernChar={char.modernChar} size={60} animated />
                    </div>
                    <div>
                      <div className="font-xiaowei text-lg text-ink">{form.label}</div>
                      <div className="text-xs text-ink-muted">{STAGE_DESC[form.stage]}</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* 我的笔记 */}
          <div className="ink-card rounded-2xl p-6">
            <h2 className="font-xiaowei text-xl text-ink mb-3 flex items-center gap-2">
              <Save size={20} className="text-gold-dark" />
              我的笔记
            </h2>
            <textarea
              value={note}
              onChange={(e) => {
                setNote(e.target.value);
                setSaved(false);
              }}
              placeholder="在此记录你对这个字的理解、联想或学习心得…"
              className="w-full min-h-[120px] rounded-md border border-ink-muted/30 bg-paper-light/50 p-3 text-ink-light resize-y focus:outline-none focus:border-cinnabar/50 focus:ring-1 focus:ring-cinnabar/30"
            />
            <div className="mt-3 flex items-center justify-between">
              <span
                className={`text-sm transition-opacity ${saved ? 'opacity-100 text-bronze' : 'opacity-0'}`}
              >
                ✓ 已保存
              </span>
              <button
                onClick={handleSave}
                className="inline-flex items-center gap-2 rounded-md bg-cinnabar px-4 py-2 text-sm text-paper-light hover:bg-cinnabar-dark transition-colors"
              >
                <Save size={16} />
                保存笔记
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* 底部删除按钮 */}
      <div className="mt-8 text-center">
        <button
          onClick={handleDelete}
          className="inline-flex items-center gap-2 rounded-md border border-cinnabar/30 px-5 py-2 text-cinnabar hover:bg-cinnabar hover:text-paper-light transition-colors"
        >
          <Trash2 size={16} />
          从记录本删除
        </button>
      </div>
    </div>
  );
}
