interface AppState {
  // 用户
  user: User | null;
  users: User[];
  login: (username: string, password: string) => { success: boolean; message: string };
  register: (username: string, password: string) => { success: boolean; message: string };
  logout: () => void;

  // 模式
  currentMode: LearnMode;
  setMode: (mode: LearnMode) => void;

  // 学习记录
  learningRecords: LearningRecord[];
  addLearningRecord: (charId: string, mode: LearnMode, correct: boolean) => void;
  learnedCharIds: string[];

  // 记录本
  notebookEntries: NotebookEntry[];
  addToNotebook: (charId: string) => void;
  removeFromNotebook: (charId: string) => void;
  updateNote: (charId: string, note: string) => void;
  isInNotebook: (charId: string) => boolean;

  // 打卡
  checkins: Checkin[];
  checkinToday: (charId?: string) => void;
  isCheckedInToday: boolean;

  // 成就
  unlockedAchievements: UnlockedAchievement[];
  newlyUnlocked: string | null;
  clearNewlyUnlocked: () => void;
  checkAchievements: () => void;

  // 社区
  communityPosts: CommunityPost[];
  addCommunityPost: (post: Partial<CommunityPost>) => void;
  likePost: (postId: string) => void;
  addComment: (postId: string, content: string) => void;

  // 数据加载
  loadUserData: () => void;
}

export const useStore = create<AppState>((set, get) => ({
  user: LS.get<User | null>('zcgj_user', null),
  users: LS.get<User[]>('zcgj_users', []),
  currentMode: LS.get<LearnMode>('zcgj_mode', 'decoder'),

  learningRecords: [],
  notebookEntries: [],
  checkins: [],
  unlockedAchievements: [],
  newlyUnlocked: null,
  communityPosts: LS.get<CommunityPost[]>('zcgj_community', SEED_POSTS),

  learnedCharIds: [],
  isCheckedInToday: false,

  login: (username, password) => {
    const users = LS.get<User[]>('zcgj_users', []);
    const found = users.find((u) => u.username === username && u.password === password);
    if (!found) return { success: false, message: '用户名或密码错误' };
    LS.set('zcgj_user', found);
    set({ user: found });
    get().loadUserData();
    return { success: true, message: '登录成功' };
  },

  register: (username, password) => {
    if (username.trim().length < 2) return { success: false, message: '用户名至少 2 个字符' };
    if (password.length < 4) return { success: false, message: '密码至少 4 位' };
    const users = LS.get<User[]>('zcgj_users', []);
    if (users.some((u) => u.username === username)) {
      return { success: false, message: '用户名已存在' };
    }
    const newUser: User = {
      id: `user_${Date.now()}`,
      username: username.trim(),
      password,
      avatar: username.trim()[0],
      level: 1,
      exp: 0,
      totalLearned: 0,
      streakDays: 0,
      createdAt: Date.now(),
    };
    users.push(newUser);
    LS.set('zcgj_users', users);
    LS.set('zcgj_user', newUser);
    set({ user: newUser, users });
    get().loadUserData();
    return { success: true, message: '注册成功' };
  },

  logout: () => {
    LS.remove('zcgj_user');
    set({ user: null, learningRecords: [], notebookEntries: [], checkins: [], unlockedAchievements: [] });
  },

  setMode: (mode) => {
    LS.set('zcgj_mode', mode);
    set({ currentMode: mode });
  },

  addLearningRecord: (charId, mode, correct) => {
    const user = get().user;
    if (!user) return;
    const record: LearningRecord = {
      id: `lr_${Date.now()}`,
      userId: user.id,
      charId,
      mode,
      correct,
      learnedAt: Date.now(),
    };
    const records = [...get().learningRecords, record];
    const learnedCharIds = [...new Set(records.map((r) => r.charId))];

    // 更新用户经验
    const updatedUser: User = {
      ...user,
      exp: user.exp + (correct ? 2 : 1),
      totalLearned: learnedCharIds.length,
      level: getLevelFromExp(user.exp + (correct ? 2 : 1)),
    };
    LS.set('zcgj_user', updatedUser);
    const allUsers = LS.get<User[]>('zcgj_users', []);
    LS.set('zcgj_users', allUsers.map((u) => (u.id === user.id ? updatedUser : u)));

    // 保存学习记录
    const userRecords = LS.get<LearningRecord[]>(`zcgj_learning_${user.id}`, []);
    userRecords.push(record);
    LS.set(`zcgj_learning_${user.id}`, userRecords);

    set({ learningRecords: records, learnedCharIds, user: updatedUser });
    get().checkAchievements();
  },

  addToNotebook: (charId) => {
    const user = get().user;
    if (!user) return;
    if (get().isInNotebook(charId)) return;
    const entry: NotebookEntry = {
      id: `nb_${Date.now()}`,
      userId: user.id,
      charId,
      note: '',
      addedAt: Date.now(),
    };
    const entries = [...get().notebookEntries, entry];
    LS.set(`zcgj_notebook_${user.id}`, entries);
    set({ notebookEntries: entries });
    get().checkAchievements();
  },

  removeFromNotebook: (charId) => {
    const user = get().user;
    if (!user) return;
    const entries = get().notebookEntries.filter((e) => e.charId !== charId);
    LS.set(`zcgj_notebook_${user.id}`, entries);
    set({ notebookEntries: entries });
  },

  updateNote: (charId, note) => {
    const user = get().user;
    if (!user) return;
    const entries = get().notebookEntries.map((e) =>
      e.charId === charId ? { ...e, note } : e,
    );
    LS.set(`zcgj_notebook_${user.id}`, entries);
    set({ notebookEntries: entries });
  },

  isInNotebook: (charId) => get().notebookEntries.some((e) => e.charId === charId),

  checkinToday: (charId) => {
    const user = get().user;
    if (!user) return;
    const today = todayStr();
    if (get().checkins.some((c) => c.date === today)) return;

    // 计算连续天数
    const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
    const prevCheckins = get().checkins;
    const streak = prevCheckins.some((c) => c.date === yesterday)
      ? user.streakDays + 1
      : 1;

    const checkin: Checkin = {
      id: `ci_${Date.now()}`,
      userId: user.id,
      date: today,
      charId,
    };
    const checkins = [...prevCheckins, checkin];
    LS.set(`zcgj_checkins_${user.id}`, checkins);

    const updatedUser: User = { ...user, streakDays: streak, exp: user.exp + 3 };
    LS.set('zcgj_user', updatedUser);
    const allUsers = LS.get<User[]>('zcgj_users', []);
    LS.set('zcgj_users', allUsers.map((u) => (u.id === user.id ? updatedUser : u)));

    set({ checkins, isCheckedInToday: true, user: updatedUser });
    get().checkAchievements();
  },

  checkAchievements: () => {
    const user = get().user;
    if (!user) return;
    const { learnedCharIds, notebookEntries, checkins } = get();
    const unlocked = get().unlockedAchievements;
    const unlockedIds = unlocked.map((a) => a.achievementId);

    const totalLikes = get()
      .communityPosts.filter((p) => p.userId === user.id)
      .reduce((sum, p) => sum + p.likes, 0);

    const checks: Record<string, boolean> = {
      first_step: learnedCharIds.length >= 1,
      scholar_10: learnedCharIds.length >= 10,
      scholar_24: learnedCharIds.length >= ORACLE_CHARS.length,
      streak_7: user.streakDays >= 7,
      game_master: get().learningRecords.some(
        (r) => r.mode === 'game' && r.correct,
      ) && get().learningRecords.filter((r) => r.mode === 'game').length >= ORACLE_CHARS.length,
      collector: notebookEntries.length >= 15,
      social_butterfly: totalLikes >= 10,
    };

    let newlyUnlocked: string | null = null;
    const newUnlocks: UnlockedAchievement[] = [];
    for (const ach of ACHIEVEMENTS) {
      if (checks[ach.id] && !unlockedIds.includes(ach.id)) {
        const unlock: UnlockedAchievement = {
          achievementId: ach.id,
          unlockedAt: Date.now(),
        };
        newUnlocks.push(unlock);
        if (!newlyUnlocked) newlyUnlocked = ach.id;
      }
    }

    if (newUnlocks.length > 0) {
      const allUnlocked = [...unlocked, ...newUnlocks];
      LS.set(`zcgj_achievements_${user.id}`, allUnlocked);
      set({ unlockedAchievements: allUnlocked, newlyUnlocked });
    }
  },

  clearNewlyUnlocked: () => set({ newlyUnlocked: null }),

  addCommunityPost: (post) => {
    const user = get().user;
    if (!user) return;
    const newPost: CommunityPost = {
      id: `post_${Date.now()}`,
      userId: user.id,
      username: user.username,
      avatar: user.avatar,
      type: post.type || 'learn',
      charId: post.charId,
      charName: post.charName,
      content: post.content || '',
      likes: 0,
      likedBy: [],
      comments: [],
      createdAt: Date.now(),
    };
    const posts = [newPost, ...get().communityPosts];
    LS.set('zcgj_community', posts);
    set({ communityPosts: posts });
    get().checkAchievements();
  },

  likePost: (postId) => {
    const user = get().user;
    if (!user) return;
    const posts = get().communityPosts.map((p) => {
      if (p.id !== postId) return p;
      const liked = p.likedBy.includes(user.id);
      return {
        ...p,
        likes: liked ? p.likes - 1 : p.likes + 1,
        likedBy: liked ? p.likedBy.filter((id) => id !== user.id) : [...p.likedBy, user.id],
      };
    });
    LS.set('zcgj_community', posts);
    set({ communityPosts: posts });
    get().checkAchievements();
  },

  addComment: (postId, content) => {
    const user = get().user;
    if (!user) return;
    const comment: Comment = {
      id: `cm_${Date.now()}`,
      userId: user.id,
      username: user.username,
      avatar: user.avatar,
      content,
      createdAt: Date.now(),
    };
    const posts = get().communityPosts.map((p) =>
      p.id === postId ? { ...p, comments: [...p.comments, comment] } : p,
    );
    LS.set('zcgj_community', posts);
    set({ communityPosts: posts });
  },

  loadUserData: () => {
    const user = get().user;
    if (!user) {
      set({
        learningRecords: [],
        notebookEntries: [],
        checkins: [],
        unlockedAchievements: [],
        learnedCharIds: [],
        isCheckedInToday: false,
      });
      return;
    }
    const records = LS.get<LearningRecord[]>(`zcgj_learning_${user.id}`, []);
    const notebook = LS.get<NotebookEntry[]>(`zcgj_notebook_${user.id}`, []);
    const checkins = LS.get<Checkin[]>(`zcgj_checkins_${user.id}`, []);
    const achievements = LS.get<UnlockedAchievement[]>(`zcgj_achievements_${user.id}`, []);
    const today = todayStr();
    set({
      learningRecords: records,
      notebookEntries: notebook,
      checkins,
      unlockedAchievements: achievements,
      learnedCharIds: [...new Set(records.map((r) => r.charId))],
      isCheckedInToday: checkins.some((c) => c.date === today),
    });
    get().checkAchievements();
  },
}));
