import { Link } from 'react-router-dom';
import { useStore } from '@/store/useStore';
import { ACHIEVEMENTS, getLevelTitle } from '@/data/achievements';
import { ORACLE_CHARS, CATEGORY_LABELS, getCharById } from '@/data/oracleChars';
import * as LucideIcons from 'lucide-react';
import {
  User, Flame, BookOpen, Award, Calendar, Lock, TrendingUp,
  Trophy, Archive, Heart, ScrollText, LogIn,
} from 'lucide-react';

const CAT_COLORS: Record<string, string> = {
  nature: 'bg-bronze',
  body: 'bg-cinnabar',
  animal: 'bg-gold',
  object: 'bg-ink-light',
};

const fmtDate = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

export default function Profile() {
  const user = useStore((s) => s.user);
  const learnedCharIds = useStore((s) => s.learnedCharIds);
  const learningRecords = useStore((s) => s.learningRecords);
  const notebookEntries = useStore((s) => s.notebookEntries);
  const checkins = useStore((s) => s.checkins);
  const isCheckedInToday = useStore((s) => s.isCheckedInToday);
  const checkinToday = useStore((s) => s.checkinToday);
  const unlockedAchievements = useStore((s) => s.unlockedAchievements);

  if (!user) {
    return (
      <div className="container mx-auto max-w-md px-4 py-24 text-center">
        <User size={64} className="mx-auto text-ink-muted mb-4" />
        <h2 className="font-xiaowei text-3xl text-ink mb-2">尚未登录</h2>
        <p className="text-ink-muted mb-6">登录后查看你的甲骨文学习之旅</p>
        <Link
          to="/auth"
          className="inline-flex items-center gap-2 rounded-md bg-cinnabar px-6 py-3 text-paper-light hover:bg-cinnabar-dark transition-colors"
        >
          <LogIn size={18} /> 前往登录
        </Link>
      </div>
    );
  }

  const title = getLevelTitle(user.exp);
  const expInLevel = user.exp % 10;
  const expProgress = expInLevel * 10;
  const memberSince = new Date(user.createdAt).toLocaleDateString('zh-CN', {
    year: 'numeric', month: 'long', day: 'numeric',
  });

  // 分类分布
  const categoryCounts: Record<string, number> = { nature: 0, body: 0, animal: 0, object: 0 };
  learnedCharIds.forEach((id) => {
    const ch = getCharById(id);
    if (ch) categoryCounts[ch.category]++;
  });
  const maxCat = Math.max(1, ...Object.values(categoryCounts));

  // 近 7 天学习记录
  const last7 = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - i));
    return { key: fmtDate(d), label: `${d.getMonth() + 1}/${d.getDate()}` };
  });
  const timelineCounts = last7.map(({ key }) =>
    learningRecords.filter((r) => fmtDate(new Date(r.learnedAt)) === key).length,
  );
  const maxTimeline = Math.max(1, ...timelineCounts);
  const gameCount = learningRecords.filter((r) => r.mode === 'game').length;

  // 日历
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const todayDate = now.getDate();
  const checkinDates = new Set(checkins.map((c) => c.date));
  const weekdays = ['日', '一', '二', '三', '四', '五', '六'];

  const unlockedMap = new Map(unlockedAchievements.map((a) => [a.achievementId, a.unlockedAt]));

  const stats = [
    { label: '已学甲骨文', value: `${learnedCharIds.length}/${ORACLE_CHARS.length}`, icon: BookOpen, color: 'text-cinnabar' },
    { label: '游戏答题数', value: gameCount, icon: TrendingUp, color: 'text-bronze' },
    { label: '收藏数', value: notebookEntries.length, icon: Archive, color: 'text-gold-dark' },
    { label: '连续打卡', value: `${user.streakDays} 天`, icon: Flame, color: 'text-cinnabar' },
  ];

  return (
    <div className="container mx-auto max-w-6xl px-4 py-8 space-y-8">
      {/* ===== 用户信息卡 ===== */}
      <section className="ink-card rounded-2xl p-6 md:p-8">
        <div className="flex flex-col md:flex-row items-center md:items-start gap-6">
          <div className="flex h-20 w-20 shrink-0 items-center justify-center rounded-full bg-bronze text-paper-light font-xiaowei text-3xl shadow-lg">
            {user.avatar}
          </div>
          <div className="flex-1 text-center md:text-left">
            <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 mb-1">
              <h1 className="font-xiaowei text-2xl text-ink">{user.username}</h1>
              <span
                className="rounded-full px-3 py-0.5 text-sm font-medium"
                style={{ backgroundColor: `${title.color}22`, color: title.color }}
              >
                {title.title}
              </span>
              <span className="text-sm text-ink-muted">Lv.{user.level}</span>
            </div>
            <p className="text-sm text-ink-muted mb-3">入会于 {memberSince}</p>
            <div className="max-w-md">
              <div className="flex justify-between text-xs text-ink-muted mb-1">
                <span>经验 {user.exp}</span>
                <span>距下一级 {10 - expInLevel} 经验</span>
              </div>
              <div className="h-2.5 rounded-full bg-paper-dark overflow-hidden">
                <div
                  className="h-full bg-gradient-to-r from-cinnabar to-gold transition-all"
                  style={{ width: `${expProgress}%` }}
                />
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* ===== 学习进度仪表盘 ===== */}
      <section>
        <h2 className="font-xiaowei text-2xl text-ink mb-4 flex items-center gap-2">
          <TrendingUp className="text-cinnabar" size={22} /> 学习进度仪表盘
        </h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
          {stats.map((s) => {
            const Icon = s.icon;
            return (
              <div key={s.label} className="ink-card rounded-xl p-4">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs text-ink-muted">{s.label}</span>
                  <Icon size={16} className={s.color} />
                </div>
                <div className="font-xiaowei text-2xl text-ink">{s.value}</div>
              </div>
            );
          })}
        </div>
        <div className="grid md:grid-cols-2 gap-4">
          {/* 分类分布 */}
          <div className="ink-card rounded-xl p-5">
            <h3 className="font-medium text-ink mb-4">分类分布</h3>
            <div className="space-y-3">
              {Object.entries(CATEGORY_LABELS).map(([key, label]) => {
                const count = categoryCounts[key] || 0;
                return (
                  <div key={key}>
                    <div className="flex justify-between text-xs text-ink-light mb-1">
                      <span>{label}</span>
                      <span>{count}</span>
                    </div>
                    <div className="h-2 rounded-full bg-paper-dark overflow-hidden">
                      <div
                        className={`h-full ${CAT_COLORS[key]} transition-all`}
                        style={{ width: `${(count / maxCat) * 100}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
          {/* 近 7 天学习 */}
          <div className="ink-card rounded-xl p-5">
            <h3 className="font-medium text-ink mb-4">近 7 日学习</h3>
            <div className="flex items-end justify-between h-32 gap-2">
              {timelineCounts.map((c, i) => (
                <div key={i} className="flex-1 flex flex-col items-center gap-1">
                  <span className="text-xs text-ink-muted">{c || ''}</span>
                  <div className="w-full flex-1 flex items-end">
                    <div
                      className="w-full bg-gradient-to-t from-bronze to-bronze-light rounded-t transition-all"
                      style={{ height: `${(c / maxTimeline) * 100}%`, minHeight: c > 0 ? '4px' : '0' }}
                    />
                  </div>
                  <span className="text-xs text-ink-muted">{last7[i].label}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* ===== 打卡日历 ===== */}
      <section>
        <h2 className="font-xiaowei text-2xl text-ink mb-4 flex items-center gap-2">
          <Calendar className="text-cinnabar" size={22} /> 打卡日历
        </h2>
        <div className="ink-card rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <span className="font-medium text-ink">{year}年{month + 1}月</span>
            <div className="flex items-center gap-3 text-xs">
              <span className="flex items-center gap-1 text-ink-muted">
                <Flame size={14} className="text-cinnabar" /> 连续 {user.streakDays} 天
              </span>
              {!isCheckedInToday && (
                <button
                  onClick={() => checkinToday()}
                  className="rounded-md bg-cinnabar px-3 py-1 text-paper-light hover:bg-cinnabar-dark transition-colors"
                >
                  今日打卡
                </button>
              )}
              {isCheckedInToday && <span className="text-bronze">今日已打卡 ✓</span>}
            </div>
          </div>
          <div className="grid grid-cols-7 gap-1.5">
            {weekdays.map((w) => (
              <div key={w} className="text-center text-xs text-ink-muted py-1">{w}</div>
            ))}
            {Array.from({ length: firstDay }, (_, i) => (
              <div key={`e${i}`} />
            ))}
            {Array.from({ length: daysInMonth }, (_, i) => {
              const day = i + 1;
              const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const checked = checkinDates.has(dateStr);
              const isToday = day === todayDate;
              return (
                <div
                  key={day}
                  className={`aspect-square flex items-center justify-center rounded-md text-sm transition-colors ${
                    isToday
                      ? 'bg-cinnabar text-paper-light font-bold'
                      : checked
                      ? 'bg-bronze/20 text-bronze-dark font-medium'
                      : 'text-ink-light hover:bg-paper-dark'
                  }`}
                >
                  {day}
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* ===== 成就墙 ===== */}
      <section>
        <h2 className="font-xiaowei text-2xl text-ink mb-4 flex items-center gap-2">
          <Award className="text-gold-dark" size={22} /> 成就墙
          <span className="text-sm text-ink-muted font-sans">
            ({unlockedAchievements.length}/{ACHIEVEMENTS.length})
          </span>
        </h2>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
          {ACHIEVEMENTS.map((ach) => {
            const unlockedAt = unlockedMap.get(ach.id);
            const unlocked = !!unlockedAt;
            const Icon = (LucideIcons as any)[ach.icon] || Award;
            return (
              <div
                key={ach.id}
                className={`rounded-xl p-4 border text-center transition-all ${
                  unlocked
                    ? 'ink-card gold-glow border-gold/40'
                    : 'border-ink-muted/20 bg-paper-light opacity-60 grayscale'
                }`}
              >
                <div className="relative inline-block">
                  <Icon size={36} className={unlocked ? 'text-gold-dark' : 'text-ink-muted'} />
                  {!unlocked && (
                    <Lock
                      size={14}
                      className="absolute -bottom-1 -right-1 text-paper-light bg-ink-muted rounded-full p-0.5"
                    />
                  )}
                </div>
                <div className="font-xiaowei text-sm text-ink mt-2">{ach.name}</div>
                <div className="text-xs text-ink-muted mt-1 leading-relaxed">{ach.description}</div>
                {unlocked && unlockedAt && (
                  <div className="text-xs text-bronze mt-2">
                    {new Date(unlockedAt).toLocaleDateString('zh-CN')}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );
}
