import type { OracleChar, EvolutionForm } from '@/types';

interface OracleGlyphProps {
  char: OracleChar;
  size?: number;
  className?: string;
  animated?: boolean;
  color?: string;
}

// 甲骨文 SVG 展示组件
export default function OracleGlyph({
  char,
  size = 120,
  className = '',
  animated = false,
  color = '#1A1814',
}: OracleGlyphProps) {
  return (
    <svg
      viewBox="0 0 100 100"
      width={size}
      height={size}
      className={className}
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        d={char.svgPath}
        fill="none"
        stroke={color}
        strokeWidth={4}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={animated ? 'oracle-stroke' : ''}
      />
    </svg>
  );
}

interface EvolutionGlyphProps {
  form: EvolutionForm;
  modernChar: string;
  size?: number;
  color?: string;
  animated?: boolean;
}

// 演变阶段字形展示
export function EvolutionGlyph({
  form,
  modernChar,
  size = 80,
  color = '#1A1814',
  animated = false,
}: EvolutionGlyphProps) {
  if (form.stage === 'regular' || !form.svgPath) {
    return (
      <span
        style={{ fontSize: size * 0.7, color, fontFamily: '"Noto Serif SC", serif', fontWeight: 700 }}
        className="leading-none"
      >
        {modernChar}
      </span>
    );
  }
  return (
    <svg
      viewBox="0 0 100 100"
      width={size}
      height={size}
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        d={form.svgPath}
        fill="none"
        stroke={color}
        strokeWidth={form.strokeWidth || 4}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={animated ? 'oracle-stroke' : ''}
      />
    </svg>
  );
}
