import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useStore } from '@/store/useStore';
import { ORACLE_CHARS } from '@/data/oracleChars';
import type { OracleChar } from '@/types';
import OracleGlyph from '@/components/OracleGlyph';
import ModeSwitcher from '@/components/ModeSwitcher';
import { Trophy, Clock, Flame, Check, X, RotateCcw, Share2, ArrowRight, Play } from 'lucide-react';

interface Question {
  char: OracleChar;
  options: string[];
}

const QUESTION_TIME = 15;
const TOTAL_QUESTIONS = 10;
const BASE_SCORE = 10;

// 打乱数组
function shuffle<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// 生成 10 道题目：随机抽取 10 个字，每个字配 3 个干扰项
function generateQuestions(): Question[] {
  const chars = shuffle(ORACLE_CHARS).slice(0, TOTAL_QUESTIONS);
  return chars.map((char) => {
    const distractors = shuffle(ORACLE_CHARS.filter((c) => c.id !== char.id))
      .slice(0, 3)
      .map((c) => c.modernChar);
    return { char, options: shuffle([char.modernChar, ...distractors]) };
  });
}

export default function Game() {
  const navigate = useNavigate();
  const user = useStore((s) => s.user);
  const addLearningRecord = useStore((s) => s.addLearningRecord);
  const addCommunityPost = useStore((s) => s.addCommunityPost);

  const [gameState, setGameState] = useState<'idle' | 'playing' | 'result'>('idle');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [score, setScore] = useState(0);
  const [combo, setCombo] = useState(0);
  const [maxCombo, setMaxCombo] = useState(0);
  const [correctCount, setCorrectCount] = useState(0);
  const [timeLeft, setTimeLeft] = useState(QUESTION_TIME);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [isCorrect, setIsCorrect] = useState(false);
  const [shared, setShared] = useState(false);

  const currentQuestion = questions[currentIdx];

  const startGame = () => {
    setQuestions(generateQuestions());
    setCurrentIdx(0);
    setScore(0);
    setCombo(0);
    setMaxCombo(0);
    setCorrectCount(0);
    setTimeLeft(QUESTION_TIME);
    setSelectedAnswer(null);
    setIsCorrect(false);
    setShared(false);
    setGameState('playing');
  };

  const handleAnswer = (answer: string) => {
    if (selectedAnswer !== null || !currentQuestion) return;
    const correct = answer === currentQuestion.char.modernChar;
    setSelectedAnswer(answer);
    setIsCorrect(correct);

    if (correct) {
      const newCombo = combo + 1;
      const bonus = Math.min(newCombo - 1, 5) * 2;
      setScore((s) => s + BASE_SCORE + bonus);
      setCombo(newCombo);
      setMaxCombo((m) => Math.max(m, newCombo));
      setCorrectCount((c) => c + 1);
    } else {
      setCombo(0);
    }

    if (user) {
      addLearningRecord(currentQuestion.char.id, 'game', correct);
    }

    setTimeout(() => {
      if (currentIdx + 1 >= TOTAL_QUESTIONS) {
        setGameState('result');
      } else {
        setCurrentIdx((i) => i + 1);
        setTimeLeft(QUESTION_TIME);
        setSelectedAnswer(null);
        setIsCorrect(false);
      }
    }, 1500);
  };

  // 倒计时
  useEffect(() => {
    if (gameState !== 'playing' || selectedAnswer !== null) return;
    if (timeLeft <= 0) {
      handleAnswer('');
      return;
    }
    const timer = setInterval(() => setTimeLeft((t) => t - 1), 1000);
    return () => clearInterval(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gameState, timeLeft, selectedAnswer]);

  const handleShare = () => {
    if (!user || shared) return;
    addCommunityPost({
      type: 'learn',
      content: `我在「象形猜谜」中答对 ${correctCount}/${TOTAL_QUESTIONS} 题，最高 ${maxCombo} 连击，得分 ${score} 分！来挑战甲骨文猜谜吧～`,
    });
    setShared(true);
  };

  // ===== 开始界面 =====
  if (gameState === 'idle') {
    return (
      <div className="container mx-auto max-w-4xl px-4 py-12">
        <div className="flex justify-center mb-8">
          <ModeSwitcher size="lg" />
        </div>
        <div className="ink-card rounded-2xl p-8 md:p-12 text-center animate-fade-up">
          <div className="inline-flex items-center gap-2 rounded-full border border-gold/40 bg-paper-light px-4 py-1.5 text-sm text-gold-dark mb-6">
            <Play size={14} />
            <span>象形猜谜挑战</span>
          </div>
          <h1 className="font-brush text-6xl md:text-7xl text-ink mb-4">象形猜谜</h1>
          <p className="font-xiaowei text-xl text-ink-light mb-8">
            看甲骨文，猜现代汉字，挑战你的象形直觉
          </p>

          <div className="grid sm:grid-cols-3 gap-4 mb-8 text-left">
            <div className="rounded-xl bg-paper p-5 border border-ink-muted/20">
              <div className="flex items-center gap-2 text-cinnabar mb-2">
                <Trophy size={18} />
                <span className="font-medium">10 道题</span>
              </div>
              <p className="text-sm text-ink-muted">从 {ORACLE_CHARS.length} 个甲骨文中随机抽取</p>
            </div>
            <div className="rounded-xl bg-paper p-5 border border-ink-muted/20">
              <div className="flex items-center gap-2 text-bronze mb-2">
                <Clock size={18} />
                <span className="font-medium">每题 15 秒</span>
              </div>
              <p className="text-sm text-ink-muted">倒计时结束自动判错</p>
            </div>
            <div className="rounded-xl bg-paper p-5 border border-ink-muted/20">
              <div className="flex items-center gap-2 text-gold-dark mb-2">
                <Flame size={18} />
                <span className="font-medium">连击加分</span>
              </div>
              <p className="text-sm text-ink-muted">连续答对获得奖励分</p>
            </div>
          </div>

          {!user && (
            <p className="text-sm text-ink-muted mb-6 italic">
              登录后可保存学习记录并解锁成就，未登录也可游玩
            </p>
          )}

          <button
            onClick={startGame}
            className="inline-flex items-center gap-2 rounded-lg bg-cinnabar px-8 py-4 text-lg font-medium text-paper-light hover:bg-cinnabar-dark transition-colors shadow-md"
          >
            <Play size={20} />
            开始挑战
          </button>
        </div>
      </div>
    );
  }

  // ===== 结束界面 =====
  if (gameState === 'result') {
    const allCorrect = correctCount === TOTAL_QUESTIONS;
    return (
      <div className="container mx-auto max-w-3xl px-4 py-12">
        <div className="ink-card rounded-2xl p-8 md:p-12 text-center animate-fade-up">
          <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gold/15 mb-6">
            <Trophy size={40} className="text-gold-dark" />
          </div>
          <h2 className="font-brush text-5xl text-ink mb-2">挑战结束</h2>
          <p className="text-ink-muted mb-8">来看看你的成绩</p>

          <div className="grid grid-cols-3 gap-4 mb-8">
            <div className="rounded-xl bg-paper p-5 border border-ink-muted/20">
              <div className="text-sm text-ink-muted mb-1">最终得分</div>
              <div className="font-xiaowei text-4xl text-cinnabar">{score}</div>
            </div>
            <div className="rounded-xl bg-paper p-5 border border-ink-muted/20">
              <div className="text-sm text-ink-muted mb-1">答对题数</div>
              <div className="font-xiaowei text-4xl text-bronze">
                {correctCount}
                <span className="text-lg text-ink-muted">/{TOTAL_QUESTIONS}</span>
              </div>
            </div>
            <div className="rounded-xl bg-paper p-5 border border-ink-muted/20">
              <div className="text-sm text-ink-muted mb-1">最高连击</div>
              <div className="font-xiaowei text-4xl text-gold-dark">{maxCombo}</div>
            </div>
          </div>

          {allCorrect && user && (
            <div className="rounded-xl border border-gold/40 bg-gold/10 p-4 mb-6 flex items-center justify-center gap-2 text-gold-dark">
              <Trophy size={18} />
              <span className="font-medium">全部答对！成就已解锁</span>
            </div>
          )}

          {shared && (
            <p className="text-sm text-bronze mb-4 flex items-center justify-center gap-1">
              <Check size={14} /> 已分享到社区
            </p>
          )}

          <div className="flex flex-wrap justify-center gap-3">
            {user && !shared && (
              <button
                onClick={handleShare}
                className="inline-flex items-center gap-2 rounded-lg border border-bronze px-5 py-3 text-bronze hover:bg-bronze hover:text-paper-light transition-colors"
              >
                <Share2 size={18} />
                分享到社区
              </button>
            )}
            <button
              onClick={startGame}
              className="inline-flex items-center gap-2 rounded-lg bg-cinnabar px-5 py-3 text-paper-light hover:bg-cinnabar-dark transition-colors"
            >
              <RotateCcw size={18} />
              再玩一局
            </button>
            <button
              onClick={() => navigate('/decoder')}
              className="inline-flex items-center gap-2 rounded-lg border border-ink-muted/30 px-5 py-3 text-ink-light hover:bg-paper-dark transition-colors"
            >
              返回解字器
              <ArrowRight size={18} />
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ===== 游戏中 =====
  if (!currentQuestion) return null;
  const progressPercent = ((currentIdx + 1) / TOTAL_QUESTIONS) * 100;
  const answered = selectedAnswer !== null;

  return (
    <div className="container mx-auto max-w-3xl px-4 py-8">
      {/* 顶部信息栏 */}
      <div className="grid grid-cols-4 gap-3 mb-4">
        <div className="ink-card rounded-lg p-3 text-center">
          <div className="text-xs text-ink-muted mb-0.5">得分</div>
          <div className="font-xiaowei text-2xl text-cinnabar">{score}</div>
        </div>
        <div className="ink-card rounded-lg p-3 text-center">
          <div className="text-xs text-ink-muted mb-0.5">连击</div>
          <div className={`font-xiaowei text-2xl flex items-center justify-center gap-1 ${combo >= 2 ? 'text-gold-dark' : 'text-ink'}`}>
            {combo >= 2 && <Flame size={16} />}
            x{combo}
          </div>
        </div>
        <div className="ink-card rounded-lg p-3 text-center">
          <div className="text-xs text-ink-muted mb-0.5">倒计时</div>
          <div className={`font-xiaowei text-2xl flex items-center justify-center gap-1 ${timeLeft <= 5 ? 'text-cinnabar' : 'text-ink'}`}>
            <Clock size={16} />
            {timeLeft}s
          </div>
        </div>
        <div className="ink-card rounded-lg p-3 text-center">
          <div className="text-xs text-ink-muted mb-0.5">进度</div>
          <div className="font-xiaowei text-2xl text-bronze">
            {currentIdx + 1}
            <span className="text-sm text-ink-muted">/{TOTAL_QUESTIONS}</span>
          </div>
        </div>
      </div>

      {/* 进度条 */}
      <div className="h-1.5 rounded-full bg-paper-dark overflow-hidden mb-6">
        <div
          className="h-full bg-gradient-to-r from-cinnabar to-gold transition-all duration-500"
          style={{ width: `${progressPercent}%` }}
        />
      </div>

      {/* 题目区 */}
      <div className="ink-card rounded-2xl p-6 md:p-8">
        <p className="text-center text-sm text-ink-muted mb-4">下面这个甲骨文对应哪个现代汉字？</p>
        <div className="flex justify-center mb-6">
          <div className="rounded-xl bg-paper p-6 border border-ink-muted/20">
            <OracleGlyph char={currentQuestion.char} size={180} animated />
          </div>
        </div>

        {/* 选项 */}
        <div className="grid grid-cols-2 gap-3">
          {currentQuestion.options.map((opt) => {
            const isCorrectOpt = opt === currentQuestion.char.modernChar;
            const isSelected = selectedAnswer === opt;
            let cls = 'border-ink-muted/30 bg-paper-light hover:border-cinnabar/40 hover:bg-paper cursor-pointer';
            if (answered) {
              if (isCorrectOpt) {
                cls = 'border-bronze bg-bronze/15 text-bronze-dark';
              } else if (isSelected) {
                cls = 'border-cinnabar bg-cinnabar/15 text-cinnabar-dark';
              } else {
                cls = 'border-ink-muted/20 bg-paper-light opacity-50';
              }
            }
            return (
              <button
                key={opt}
                onClick={() => handleAnswer(opt)}
                disabled={answered}
                className={`relative flex items-center justify-center rounded-lg border-2 py-5 font-serif text-3xl transition-all ${cls}`}
              >
                {opt}
                {answered && isCorrectOpt && (
                  <Check size={20} className="absolute top-2 right-2 text-bronze" />
                )}
                {answered && isSelected && !isCorrectOpt && (
                  <X size={20} className="absolute top-2 right-2 text-cinnabar" />
                )}
              </button>
            );
          })}
        </div>

        {/* 反馈 */}
        {answered && (
          <div className={`mt-5 text-center rounded-lg p-3 animate-fade-in ${isCorrect ? 'bg-bronze/10 text-bronze-dark' : 'bg-cinnabar/10 text-cinnabar-dark'}`}>
            {isCorrect ? (
              <span className="flex items-center justify-center gap-2 font-medium">
                <Check size={18} /> 正确！+{BASE_SCORE + Math.min(Math.max(combo - 1, 0), 5) * 2} 分
              </span>
            ) : (
              <span className="flex items-center justify-center gap-2 font-medium">
                <X size={18} /> 正确答案：{currentQuestion.char.modernChar}
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
